import React, { useEffect, useRef, useState } from "react";
import * as faceapi from "face-api.js";

const Home = () => {
  const videoRef = useRef(null);
  const [status, setStatus] = useState("🔄 Iniciando cámara...");
  const [imageList, setImageList] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);

  const lastMove = useRef(Date.now());

  useEffect(() => {
    const loadModels = async () => {
      const MODEL_URL = process.env.PUBLIC_URL + "/models";
      await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
      await faceapi.nets.faceLandmark68TinyNet.loadFromUri(MODEL_URL);
    };
    loadModels();
  }, []);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { width: 640, height: 480, facingMode: "user" },
          audio: false,
        });

        const video = videoRef.current;
        video.srcObject = stream;
        video.onloadedmetadata = () => {
          video.play().then(() => {
            setStatus("✅ Cámara activa");
            detectarMovimiento();
          });
        };
      } catch (err) {
        console.error("Error cámara:", err);
        setStatus("❌ No se pudo acceder a la cámara");
      }
    };

    const detectarMovimiento = async () => {
      const video = videoRef.current;
      const options = new faceapi.TinyFaceDetectorOptions({ inputSize: 160 });

      setInterval(async () => {
        if (!video || video.paused || video.ended) return;

        const result = await faceapi
          .detectSingleFace(video, options)
          .withFaceLandmarks(true);

        if (result && result.landmarks) {
          const nose = result.landmarks.getNose()[3];
          const x = nose.x;
          const now = Date.now();

          if (now - lastMove.current > 1500) {
            if (x < 220 && currentIndex < imageList.length - 1) {
              setCurrentIndex((i) => i + 1);
              lastMove.current = now;
            } else if (x > 420 && currentIndex > 0) {
              setCurrentIndex((i) => i - 1);
              lastMove.current = now;
            }
          }
        }
      }, 500);
    };

    startCamera();
  }, [currentIndex, imageList.length]);

  const handleFileChange = (event) => {
    const files = Array.from(event.target.files).filter((file) =>
      file.type.startsWith("image/")
    );

    if (files.length === 0) {
      alert("Por favor seleccioná imágenes JPG o PNG.");
      return;
    }

    const urls = files.map((file) => URL.createObjectURL(file));
    setImageList(urls);
    setCurrentIndex(0);
  };

  return (
    <div style={{ textAlign: "center", padding: "10px", maxWidth: "100%" }}>
      <h2 style={{ fontSize: "1.5rem" }}>🖼️ Navegación de Imágenes con movimientos de cabeza</h2>
      <p style={{ fontSize: "1rem" }}>{status}</p>

      <video
        ref={videoRef}
        autoPlay
        muted
        playsInline
        style={{
          width: "120px", // más pequeño
          height: "90px",
          border: "2px solid #ccc",
          marginBottom: "10px",
          borderRadius: "8px",
        }}
      />

      <div style={{ marginBottom: "20px" }}>
        <input type="file" accept="image/*" multiple onChange={handleFileChange} />
      </div>

      {imageList.length > 0 ? (
        <div style={{ padding: "0 10px" }}>
          <img
            src={imageList[currentIndex]}
            alt={`Imagen ${currentIndex + 1}`}
            style={{
              width: "100%",
              height: "auto",
              maxHeight: "70vh",
              objectFit: "contain",
              border: "1px solid #999",
              borderRadius: "8px",
            }}
          />
          <p style={{ marginTop: "10px" }}>
            Imagen {currentIndex + 1} de {imageList.length}
          </p>
        </div>
      ) : (
        <p>📂 Seleccioná imágenes para comenzar</p>
      )}
    </div>
  );
};

export { Home };
